contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2);
        c.addToBalance{value: amount1}(); if (__ESBMC_reverted()) return;
        c.addToBalance{value: amount2}(); if (__ESBMC_reverted()) return;
        uint recorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        require(recorded == amount1 + amount2);
        uint balBefore = address(c).balance;
        require(balBefore >= recorded);
        c.withdrawBalance(); if (__ESBMC_reverted()) return;
        assert(c.getBalance(address(this)) == 0 && address(c).balance == balBefore - recorded);
    }
    receive() external payable {}
}

