// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2);
        try c.addToBalance{value: amount1}() {} catch { return; }
        try c.addToBalance{value: amount2}() {} catch { return; }
        uint256 recorded;
        try c.getBalance(address(this)) returns (uint256 __r) { recorded = __r; } catch { return; }
        vm.assume(recorded == amount1 + amount2);
        uint balBefore = address(c).balance;
        vm.assume(balBefore >= recorded);
        try c.withdrawBalance() {} catch { return; }
        assertTrue(c.getBalance(address(this)) == 0 && address(c).balance == balBefore - recorded);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
